// "What If You Became Pain in Real Life? 6 Bodies" — flat 2D, our own designs. One day and one night above a valley,
// 6:58 a.m. to the next morning (no day count: a clock in the corner, a status chip "6 BODIES ACTIVE", and a Shinra Tensei
// cooldown dial when the push is in play). Shots come from PLAN (story sections); each section draws by keywords in the
// narration line. Look (matches the thumbnail): stickmen with round black heads, spiky orange hair, a headband, violet
// ringed eyes, piercings and dark cloaks with red clouds; violet concentric rings in the sky, a red moon. The real body
// (yours) is thin and pale, in a chair in a stone room. Seals CANON / OUR RULE / OUR GUESS show top-left while spoken.
import { registerShot, clamp, ease } from '/engine/api.js';
import { P_THINK, P_TIRED, P_SIT, P_RUN, P_SHRUG, P_SHIVER } from '../lib/people.js';
import { P_STAND, P_POINT, P_HIPS } from '../lib/char2d.js';
import { hud, label, caption } from '../lib/hud.js';
import { frame as frame0 } from '../lib/flat2d.js';
import * as E from '../lib/sets/pn2d.js';
import { PLAN, TAGS, SECS } from './plan.js';

const f = (n) => n.toFixed(1);
const RED = E.RED, GOLD = E.GOLD, GREEN = E.GREEN, VIO = E.VIO, ORANGE = E.ORANGE, GREY = '#c8ccd8';
const TITLE = 'WHAT IF YOU BECAME PAIN?';
// the six bodies (one Path each) and their accent colours (only for the little tags; the bodies look the same)
const PATHS = ['DEVA', 'ANIMAL', 'PRETA', 'ASURA', 'NARAKA', 'HUMAN'];
const PCOL = { DEVA: '#ffd23f', ANIMAL: '#ff9a4a', PRETA: '#5ac8e0', ASURA: '#c8ccd6', NARAKA: '#b48cff', HUMAN: '#5ae08a' };
const BODY = { top: '#1c1b24', bottom: '#15151c', cloak: true, spiky: ORANGE, band: true, rinne: true, pierce: true, rim: '#e8d8ff' };
const HERO = { top: '#c8c2d4', bottom: '#4a4652', hair: 'short', rinne: true, pierce: true };
const RUTH = { top: '#e07a2a', bottom: '#2a3a4a', hair: 'ponytail', cap: '#ffd23f' };
const RUTH_RAIN = { ...RUTH, top: '#ffd23f', cap: null, hood: true };
const BOY = { top: '#4a7ae0', bottom: '#2a2d3a', hair: 'short', shorts: true };
const CLOCK = { open: '6:58 AM', eyes: '7:02 AM', push: '7:30 AM', town: '8:15 AM', dam: '9:10 AM', split: '1:00 PM', brk: '4:30 PM', visit: '6:00 PM', pick: '9:40 PM', morning: '6:10 AM' };
let SECNOW = 'open', G = 0, LINE = '', KNOW = 0, LT = 0, DUR = 3, MOVE = 0, CUT = 'wide';
const has = (line, ...w) => w.some((x) => line.toLowerCase().includes(x.toLowerCase()));
const since = (sec, ...w) => { let best = 1e9; for (const p of Object.values(PLAN)) if (p.sec === sec && has(p.line, ...w)) best = Math.min(best, p.k); return best; };
const after = (sec, ...w) => SECNOW === sec && since(sec, ...w) <= KNOW;
const timeNow = () => { const l = LINE;
  if (SECNOW === 'open' && has(l, 'six fifty-eight', 'six directions')) return '6:58 AM';
  if (SECNOW === 'split' && after('split', 'By three')) return '3:00 PM';
  if (SECNOW === 'brk' && after('brk', 'hold that rhythm')) return '5:40 PM';
  if (SECNOW === 'pick' && after('pick', 'takes the gate')) return '9:47 PM';
  if (SECNOW === 'pick' && after('pick', 'town doesn')) return '9:52 PM';
  if (SECNOW === 'morning' && after('morning', 'at noon')) return has(l, 'comments', 'Would you', 'who you want', 'next one') ? '12:01 PM' : '12:00 PM';
  return CLOCK[SECNOW]; };
const stopped = () => (SECNOW === 'visit' && after('visit', 'Everything stops')) || (SECNOW === 'pick' && KNOW < since('pick', 'Four are fine'));
const chip = () => { if (stopped()) return { text: '0 BODIES · INTERRUPTED', on: true, color: RED };
  if (SECNOW === 'pick' && after('pick', 'You let the Naraka')) return { text: '6 BODIES · NARAKA ON THE GATE', on: true, color: VIO };
  if (SECNOW === 'pick') return { text: '6 STREAMS · PICK ONE', on: true, color: RED };
  if (SECNOW === 'morning') return { text: '6 BODIES · RESTING', on: true, color: GREEN };
  return { text: '6 BODIES ACTIVE · ONE MIND', on: true, color: VIO }; };
// the Shinra Tensei dial: READY, then 5 → 0 (a cycle while the push is in play)
const dialOn = () => (SECNOW === 'push' && after('push', 'loudest one')) || SECNOW === 'split' || SECNOW === 'brk';
const dial = (U) => { if (!dialOn()) { U.html('cool', '', {}); return; } const ph = (G * 1.0) % 6.5, ready = ph < 1.5, left = Math.ceil(5 - (ph - 1.5)), col = ready ? GREEN : VIO;
  U.html('cool', `<div style="display:flex;align-items:center;gap:12px;background:rgba(10,8,14,.78);border:2px solid ${col};border-radius:12px;padding:6px 16px"><svg width="34" height="34" viewBox="-17 -17 34 34"><circle r="13" fill="none" stroke="#3a3446" stroke-width="5"/><circle r="13" fill="none" stroke="${col}" stroke-width="5" stroke-dasharray="${f(ready ? 82 : 82 * (ph - 1.5) / 5)} 82" transform="rotate(-90)"/></svg><div style="font:800 24px 'IBM Plex Mono';color:#fff;letter-spacing:.05em">SHINRA TENSEI · ${ready ? '<span style="color:' + GREEN + '">READY</span>' : '0:0' + Math.max(0, Math.min(5, left))}</div></div>`, { right: '46px', top: '170px' }, { z: 61 }); };
const chrome = (U, t, info, o = {}) => { hud(U, { title: TITLE, day: null, status: o.status || chip() });
  const tm = o.time || timeNow(), night = /PM/.test(tm) && (parseInt(tm) >= 6 && parseInt(tm) < 12), col = stopped() ? RED : VIO;
  U.html('clock', `<div style="display:flex;align-items:center;gap:14px;background:rgba(10,8,14,.78);border:2px solid ${col};border-radius:12px;padding:6px 18px"><svg width="30" height="30" viewBox="-15 -15 30 30">${night ? `<circle r="11" fill="${RED}"/><circle cx="5" cy="-3" r="10" fill="#0a0818"/>` : `<circle r="12" fill="none" stroke="${col}" stroke-width="3"/><line x1="0" y1="0" x2="0" y2="-8" stroke="#fff" stroke-width="3" stroke-linecap="round"/><line x1="0" y1="0" x2="${f(6 * Math.sin(t * 0.8))}" y2="${f(-6 * Math.cos(t * 0.8))}" stroke="#fff" stroke-width="2.5" stroke-linecap="round"/>`}</svg><div style="font:800 34px 'IBM Plex Mono';color:#fff;letter-spacing:.06em">${tm}</div></div>`, { right: '46px', top: '96px' }, { z: 61 });
  dial(U); caption(U, info, t); };
const LX = (txt) => Math.min(1180, 1840 - txt.length * 24 - 70);
const L1 = (U, t, txt, t0 = 0.3, c) => label(U, 'L1', txt, t0, t, LX(txt), 260, c ? { color: c } : {});
